from components.policy_decisions.work import compute


class TestPolicyDecisions(unittest.TestCase):
    def test_public_fixture(self):
        payload = {
            "policies": {
                "alice": [
                    {"cluster": "here", "verb": "read"},
                    {"cluster": "here", "verb": "write"},
                    {"cluster": "away", "verb": "read"},
                    {"cluster": "away", "verb": "write"},
                    {"cluster": "far", "verb": "read"},
                    {"cluster": "far", "verb": "write"},
                ],
                "bob": [{"cluster": "away", "verb": "read"}],
            },
            "events": [
                {"op": "request", "id": "a", "time": 0, "user": "alice",
                 "cluster": "away", "service": "k", "verb": "read"},
                {"op": "request", "id": "b", "time": 1, "user": "alice",
                 "cluster": "away", "service": "k", "verb": "read"},
            ],
        }
        self.assertEqual(compute(payload), {"0": True, "1": True})

    def test_policy_event_replaces_allow_list(self):
        payload = {
            "policies": {"alice": [{"cluster": "away", "verb": "read"}]},
            "events": [
                {"op": "policy", "time": 0, "user": "alice",
                 "allow": [{"cluster": "away", "verb": "write"}]},
                {"op": "request", "id": "r1", "time": 1, "user": "alice",
                 "cluster": "away", "service": "k", "verb": "read"},
                {"op": "request", "id": "r2", "time": 2, "user": "alice",
                 "cluster": "away", "service": "k", "verb": "write"},
            ],
        }
        self.assertEqual(compute(payload), {"1": False, "2": True})

    def test_service_wildcard_and_exact(self):
        payload = {
            "policies": {
                "alice": [
                    {"cluster": "away", "verb": "read", "service": "*"},
                    {"cluster": "away", "verb": "write", "service": "k"},
