                 "cluster": "away", "service": "other", "verb": "read"},
                {"op": "request", "id": "r2", "time": 1, "user": "alice",
                 "cluster": "away", "service": "other", "verb": "write"},
                {"op": "request", "id": "r3", "time": 2, "user": "alice",
                 "cluster": "away", "service": "k", "verb": "write"},
            ],
        }
        self.assertEqual(compute(payload), {"0": True, "1": False, "2": True})

    def test_unknown_user_denied(self):
        payload = {
            "policies": {},
            "events": [
                {"op": "request", "id": "r1", "time": 0, "user": "nobody",
                 "cluster": "away", "service": "k", "verb": "read"},
            ],
        }
        self.assertEqual(compute(payload), {"0": False})


